#include <stdio.h>
#include <string.h>
#include "dsky_nv_admission_check.h"
static apollo_overlay_state s,before;
int main(void){p66_bias_io io,old;enum dsky_nv_mission mission;enum dsky_nv_entry entry;enum dsky_nv_route route;uint16_t failures=0;uint8_t n,g;for(n=0;n<64u;++n)failures=(uint16_t)(failures+dsky_nv_admission_checkpoint(n,&s,&before));for(n=0;n<8u;++n)for(g=0;g<10u;++g){if(!dsky_nv_admission_checkpoint_input((uint8_t)(n*8u),&s,&io,&mission,&entry))return 2;switch(g){case 0:s.words[5]=0;break;case 1:s.words[4]=1;break;case 2:s.words[3]=1;break;case 3:s.words[6]^=1;break;case 4:s.words[7]=1;break;case 5:io.superbank=1;break;case 6:io.interrupt_enabled=2;break;case 7:entry=(enum dsky_nv_entry)4;break;case 8:mission=(enum dsky_nv_mission)2;break;default:if(entry<=DSKY_NV_NVMONOPT)s.words[01012]=8;else if(entry==DSKY_NV_NVSUB1)s.words[0123]=077700;else s.words[0160]=0200;break;}before=s;old=io;route=DSKY_NV_ALARM;if(dsky_nv_admit(&s,&io,mission,entry,&route)!=P66_BIAS_OUT_OF_SCOPE||memcmp(&s,&before,sizeof s)||memcmp(&io,&old,sizeof io)||route!=DSKY_NV_ALARM)++failures;}printf("64 full LM/CM NVSUB source states and80 unchanged invalid guards: %s\n",failures?"FAIL":"PASS");return failures?1:0;}
